window.MOTIF_CATALOG_CHUNKS[26]={"cards":[{"id":"MEJE-KW-000370","row_version":1,"title":"옆으로 피하지 않고 직선으로만 도망치기","original":"1-Dimensional Thinking","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"일직선으로 오는 위험을 옆으로 피하면 되는데도 인물이 같은 방향으로 계속 달리는 장면. 간단한 선택을 놓쳐 추격의 긴장과 비현실적인 웃음이 생긴다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-000370/index.html"},{"id":"MEJE-KW-000371","row_version":2,"title":"현실 감각이 뒤틀린 차원","original":"Acid-Trip Dimension","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"색과 형태, 물리적 규칙이 익숙한 세계와 크게 달라 여행자가 방향 감각을 잃는 다른 차원. 낯선 환경 자체가 탐험의 장애가 된다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000371/index.html"},{"id":"MEJE-KW-000372","row_version":3,"title":"넘어갈 수 있는 다른 차원","original":"Another Dimension","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"문이나 균열 같은 경로를 거쳐 현재 세계와 왕래할 수 있는 별개의 현실. 얼마나 닮았는지와 어떻게 돌아오는지가 차원 여행의 규칙을 만든다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000372/index.html"},{"id":"MEJE-KW-000373","row_version":1,"title":"서로 다른 차원의 충돌","original":"Cross-Dimensional Conflict","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"서로 다른 차원의 세력이나 세계 법칙이 접촉하면서 일어나는 대립. 침입과 방어를 넘어 한쪽의 질서가 다른 쪽의 생존을 위협할 수 있다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-000373/index.html"},{"id":"MEJE-KW-000374","row_version":1,"title":"차원 전체를 지배하는 군주","original":"Dimension Lord","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"하나의 차원이나 별도 세계 전체를 자기 영토로 삼아 다스리는 강력한 지배자 인물형. 다른 세계까지 손을 뻗을 수 있다는 점이 위협을 키운다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000374/index.html"},{"id":"MEJE-KW-000375","row_version":3,"title":"하나의 차원이 여러 세계로 갈라짐","original":"Dimension Splitting","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"처음에는 하나였던 현실이 사건이나 강력한 힘으로 둘 이상의 독립된 세계로 분리되는 설정. 갈라진 세계들의 과거와 다시 합쳐질 가능성이 세계사의 핵심이 된다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000375/index.html"},{"id":"MEJE-KW-000376","row_version":1,"title":"시공간을 베어 통로를 열기","original":"Dimensional Cutter","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"칼날이나 발톱이 보통 물체를 넘어 공간의 경계까지 가를 수 있는 능력. 절단된 틈은 이동 통로가 되거나 먼 거리의 대상을 공격하는 경로가 된다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000376/index.html"},{"id":"MEJE-KW-000377","row_version":1,"title":"차원을 자유롭게 오가는 여행자","original":"Dimensional Traveler","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"기술이나 마법, 타고난 능력으로 여러 차원 사이를 반복해서 왕래할 수 있는 인물형. 한 번 우연히 넘어간 사람과 달리 이동 경로를 스스로 선택한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000377/index.html"},{"id":"MEJE-KW-000378","row_version":2,"title":"다른 차원을 거치는 지름길","original":"Extra-Dimensional Shortcut","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13","ML-T01179","ML-T02508"],"summary":"현재 세계의 두 지점 사이를 가기 위해 잠시 다른 차원에 들어갔다가 더 유리한 출구로 나오는 이동 방식. 우회 공간의 거리와 출구 규칙이 지름길을 성립시킨다.","accent":"#497A73","tab":"#778F70","facet":"세계관·규칙","bookmark":"차원 간 이동","entry_url":"cards/MEJE-KW-000378/index.html"},{"id":"MEJE-KW-000379","row_version":2,"title":"위기에서 다른 차원으로 빠지는 비상구","original":"Extradimensional Emergency Exit","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13","ML-T01179","ML-T02508"],"summary":"도망칠 길이 막힌 순간 다른 차원으로 향하는 통로를 열어 위험을 피하는 설정. 통로를 열 수 있는 속도와 도착지의 안전이 탈출의 조건이 된다.","accent":"#497A73","tab":"#778F70","facet":"세계관·규칙","bookmark":"차원 간 이동","entry_url":"cards/MEJE-KW-000379/index.html"},{"id":"MEJE-KW-000380","row_version":1,"title":"다른 차원에서 끌어오는 동력","original":"Extradimensional Power Source","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"마법이나 장치가 현재 세계 밖의 에너지를 끌어다 사용하는 설정. 힘의 공급이 차원 사이의 연결과 그 연결을 유지하는 규칙에 의존한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000380/index.html"},{"id":"MEJE-KW-000381","row_version":2,"title":"최종전만을 위한 별도 차원","original":"Final Boss, New Dimension","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"마지막 적과 싸우기 위해 전장 자체가 다른 차원으로 옮겨지는 게임 연출. 일상 공간과 다른 풍경과 규칙이 최종 대결의 규모를 강조한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-000381/index.html"},{"id":"MEJE-KW-000382","row_version":2,"title":"차원을 오가는 장치","original":"Interdimensional Travel Device","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13","ML-T01179","ML-T02508"],"summary":"서로 다른 현실 사이에 통로를 열거나 이동자를 보내는 기계·마법 물건. 출발과 도착 위치를 얼마나 정확히 정할 수 있는지가 세계의 이동 규칙이 된다.","accent":"#497A73","tab":"#778F70","facet":"세계관·규칙","bookmark":"차원 간 이동","entry_url":"cards/MEJE-KW-000382/index.html"},{"id":"MEJE-KW-000383","row_version":2,"title":"세 차원을 넘는 공간","original":"More than Three Dimensions","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"익숙한 앞뒤·좌우·위아래 외에 추가적인 공간 방향이 존재한다는 허구 설정. 이를 감지하거나 통과할 수 있는 존재는 보통 사람과 다른 방식으로 공간을 경험한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000383/index.html"},{"id":"MEJE-KW-000385","row_version":2,"title":"감옥으로 쓰는 별도 차원","original":"Prison Dimension","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"위험한 인물이나 존재를 가두기 위해 마련된 다른 차원. 외부와의 통로를 통제하는 규칙이 탈출과 재침입의 가능성을 정한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000385/index.html"},{"id":"MEJE-KW-000386","row_version":2,"title":"쉽게 넘나드는 차원 경계","original":"Thin Dimensional Barrier","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13","ML-T01179","ML-T02508"],"summary":"두 세계 사이의 장벽이 특정 장소나 때에 약해져 사람과 사물이 뜻밖에 넘어가는 설정. 경계가 얇은 지점은 탐험과 침입의 통로가 된다.","accent":"#497A73","tab":"#778F70","facet":"세계관·규칙","bookmark":"차원 간 이동","entry_url":"cards/MEJE-KW-000386/index.html"},{"id":"MEJE-KW-000387","row_version":1,"title":"입체 영상 체험 회차","original":"Three-Dimensional Episode","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품의 한 회차를 입체 영상 관람에 맞춰 제작해 화면 밖으로 튀어나오는 듯한 장면을 전면에 내세우는 형식. 평소의 연출보다 관람 방식의 변화를 행사처럼 강조한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-000387/index.html"},{"id":"MEJE-KW-000388","row_version":2,"title":"시간 이동 뒤의 도착 위치","original":"Time and Relative Dimensions in Space","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"과거나 미래로 이동할 때 시간뿐 아니라 공간상의 어느 지점에 나타나는지도 정해야 하는 설정 문제. 고정 좌표와 움직이는 세계 중 무엇을 기준으로 삼는지가 결과를 바꾼다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000388/index.html"},{"id":"MEJE-KW-000389","row_version":1,"title":"두 차원이 뒤섞이기","original":"When Dimensions Collide","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"서로 다른 세계가 겹치면서 한쪽의 지형과 존재, 법칙이 다른 쪽으로 스며드는 전개. 섞임이 커지면 두 세계가 합쳐지거나 한쪽이 밀려날 수 있다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000389/index.html"},{"id":"MEJE-KW-000390","row_version":1,"title":"군주의 연애가 나라를 흔들기","original":"Love Ruins the Realm","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01330","ML-T01331"],"summary":"군주의 사적인 관계가 국정 방치나 동맹의 파기, 권력 승계의 혼란으로 이어지는 전개. 개인의 선택이 통치자의 책임과 부딪힌다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"군주제 사회","entry_url":"cards/MEJE-KW-000390/index.html"},{"id":"MEJE-KW-000391","row_version":1,"title":"부자가 만든 사적인 왕국","original":"Rich Recluse's Realm","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"막대한 재산을 가진 은둔자가 외부와 떨어진 넓은 공간을 사들여 자기 취향대로 꾸민 사유 영역. 거주지의 규모와 폐쇄성이 인물의 권력을 드러낸다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-000391/index.html"},{"id":"MEJE-KW-000392","row_version":2,"title":"들어간 사람을 바꾸는 왕국","original":"Fisher Kingdom","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"어떤 지역에 머무는 것만으로 인물의 몸이나 마음이 그곳의 규칙에 맞게 변하는 설정. 통치자보다 장소 자체가 주민과 방문자를 새 모습으로 만든다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000392/index.html"},{"id":"MEJE-KW-000393","row_version":1,"title":"나라의 첫 건국자","original":"Founder of the Kingdom","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"한 나라를 세운 첫 지도자로 후대의 군주와 백성이 기원으로 기억하는 인물형. 실제 행적과 후대가 만든 영웅상이 달라 갈등의 소재가 되기도 한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000393/index.html"},{"id":"MEJE-KW-000394","row_version":2,"title":"폭정의 왕국","original":"The Bad Kingdom","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01330","ML-T01331"],"summary":"지배층의 억압과 부패가 나라의 성격을 규정하는 허구의 왕국. 주민의 삶이 권력 유지에 종속되어 저항이나 외부 전쟁의 상대가 된다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"군주제 사회","entry_url":"cards/MEJE-KW-000394/index.html"},{"id":"MEJE-KW-000395","row_version":2,"title":"보호받아야 할 선한 왕국","original":"The Good Kingdom","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01330","ML-T01331"],"summary":"주인공 쪽의 평화로운 나라로 그려져 침략이나 저주로부터 지켜야 할 대상으로 기능하는 왕국. 사회 제도의 세부보다 수호할 고향이라는 역할이 앞선다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"군주제 사회","entry_url":"cards/MEJE-KW-000395/index.html"},{"id":"MEJE-KW-000396","row_version":2,"title":"어두운 비밀 위에 선 제국","original":"Empire with a Dark Secret","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01330","ML-T01333"],"summary":"겉으로 번영하고 질서정연한 제국이 실제로는 숨겨진 희생이나 폭력에 기대어 유지되는 설정. 비밀이 드러나면 통치의 정당성과 시민의 일상이 함께 흔들린다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"제국 체제","entry_url":"cards/MEJE-KW-000396/index.html"},{"id":"MEJE-KW-000397","row_version":2,"title":"보편 명칭의 연방과 고유 이름의 제국","original":"Generic Federation, Named Empire","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"서로 맞선 두 정치 세력 가운데 주인공 쪽은 '연방'처럼 넓은 체제명으로, 상대는 특정 민족·왕조·통치자의 이름을 붙인 제국으로 부르는 명명 대비. 어느 쪽을 보편적인 질서로 읽게 할지 이름만으로 암시할 수 있다. 체제명만으로 불리는 국가는 양쪽의 대비 없이 한 국가의 이름 자체가 일반명사인 경우다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000397/index.html"},{"id":"MEJE-KW-000398","row_version":1,"title":"체제명만으로 불리는 국가","original":"Generican Empire","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"국가가 고유한 역사·문화·지역 이름 대신 '은하 제국', '행성 연방'처럼 통치 형태나 규모를 뜻하는 말로만 불리는 설정. 이름의 간결함은 거대한 세력을 빠르게 인식시키지만 그 구성 사회의 개별성은 흐리게 할 수 있다. 보편 명칭의 연방과 고유 이름의 제국은 서로 맞선 두 세력의 명칭 차이에 초점을 둔다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000398/index.html"},{"id":"MEJE-KW-000399","row_version":3,"title":"선한 공화국과 악한 제국의 대립","original":"Good Republic, Evil Empire","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01330","ML-T01333"],"summary":"공화정·합의제를 영웅 쪽에, 제국·독재 체제를 적대 쪽에 배치해 정치 제도를 선악의 신호처럼 사용하는 서사 관습. 실제 제도만으로 윤리성이 결정되지는 않으며, 카드가 가리키는 것은 작품이 관객에게 건네는 빠른 구도다. 정복을 목표로 하는 악역 제국은 적대 국가 자체의 역할에 초점을 둔다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"제국 체제","entry_url":"cards/MEJE-KW-000399/index.html"},{"id":"MEJE-KW-000400","row_version":1,"title":"간접 지배하는 패권 제국","original":"Hegemonic Empire","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01330","ML-T01333"],"summary":"모든 영토를 직접 병합하지 않고 무역망·보호 약속·문화적 영향력·종속 정권을 통해 주변 국가의 선택을 좌우하는 제국 설정. 겉으로 남은 자치권과 실제 의존 관계의 간극이 갈등을 만든다. 팽창기에 있는 신흥 제국은 성장 단계, 이 카드는 지배 방식에 초점을 둔다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"제국 체제","entry_url":"cards/MEJE-KW-000400/index.html"},{"id":"MEJE-KW-000401","row_version":4,"title":"현대까지 주권을 유지한 아메리카 토착 국가","original":"Modern Mayincatec Empire","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"아메리카의 토착 국가가 식민 지배나 국가 해체를 겪지 않았거나 다른 경로로 주권을 유지해 현대 국제 질서의 한 구성원이 된 대체역사 설정. 정치 체제와 국경이 달라지는 가정을 다루며, 실제 토착 문화와 공동체가 오늘날까지 이어져 왔다는 사실과 구별한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000401/index.html"},{"id":"MEJE-KW-000402","row_version":1,"title":"쇠퇴 후 다시 일어서는 제국","original":"Resurgent Empire","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01330","ML-T01333"],"summary":"영토와 영향력을 잃은 제국 또는 그 후계 세력이 옛 위상을 회복하려고 제도·군사·동맹을 재건하는 전개. 다시 강해지는 결과보다 과거의 영광을 되찾겠다는 목표가 핵심이다. 과거의 흔적만 남은 제국은 재기의 출발점이고 팽창기에 있는 신흥 제국은 처음 성장하는 국가다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"제국 체제","entry_url":"cards/MEJE-KW-000402/index.html"},{"id":"MEJE-KW-000403","row_version":1,"title":"팽창기에 있는 신흥 제국","original":"Rising Empire","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01330","ML-T01333"],"summary":"막 형성되어 정복·교역·외교 등의 수단으로 세력권을 넓혀 가는 제국. 내부 인물에게는 개척과 성취, 주변 공동체에는 침략과 압박으로 보일 수 있어 시점에 따라 평가가 달라진다. 쇠퇴 후 다시 일어서는 제국은 과거의 위상을 회복하려는 경우다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"제국 체제","entry_url":"cards/MEJE-KW-000403/index.html"},{"id":"MEJE-KW-000404","row_version":3,"title":"악역 제국을 응원하는 관객","original":"Rooting for the Empire","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"작품이 적대로 제시한 제국이나 세력에 관객이 주인공보다 더 강하게 감정 이입해 승리를 바라는 수용 반응. 매력적인 인물·설계, 영웅의 설득력 부족, 작품이 의도한 도덕적 모호함 등 이유는 다를 수 있다. 작품 속 정복을 목표로 하는 악역 제국의 역할과 관객의 실제 선택을 구분한다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-000404/index.html"},{"id":"MEJE-KW-000405","row_version":1,"title":"지도 공간을 거대 국가로 채우기","original":"Space-Filling Empire","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"대체역사나 가상 세계의 지도를 소수의 대형 국가로 거의 빈틈없이 나누는 세계 설계 관습. 세력 간 대립과 동맹은 한눈에 보여 주지만, 지역별 정치·문화 차이와 실제 통치 가능성을 생략하기 쉽다. 특정한 정복을 목표로 하는 악역 제국 한 곳보다 세계 지도 전체의 구성 방식에 초점을 둔다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000405/index.html"},{"id":"MEJE-KW-000406","row_version":2,"title":"악역 제국의 단계별 지휘 체계","original":"Standard Evil Empire Hierarchy","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01330","ML-T01333"],"summary":"최고 통치자 아래 장군·친위대·지역 책임자 등 여러 간부를 놓고 주인공이 그들을 단계적으로 상대하게 하는 적대 조직의 구조. 지휘 계통은 권력 다툼과 중간 목표를 만들며 최종 통치자와의 대면을 뒤로 미룬다. 정복을 목표로 하는 악역 제국은 국가의 서사적 역할이고 이 카드는 내부 배치다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"제국 체제","entry_url":"cards/MEJE-KW-000406/index.html"},{"id":"MEJE-KW-000407","row_version":1,"title":"강성 제국의 쇠약한 황제","original":"Strong Empire, Shriveled Emperor","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"국가의 군사력과 행정력은 막강한데 그 정점에 선 황제는 노쇠하거나 병약해 보이는 인물 구도. 개인의 신체적 약함과 제도의 강함 사이에 대비가 생기며, 실권이 누구에게 있는지나 통치자의 다른 능력이 무엇인지 탐색하게 한다. 과거의 흔적만 남은 제국처럼 국가 자체가 약해진 설정과는 다르다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000407/index.html"},{"id":"MEJE-KW-000408","row_version":1,"title":"제국의 흥망 주기","original":"The Cycle of Empires","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01330","ML-T01333"],"summary":"제국이 팽창, 안정, 쇠퇴, 붕괴 또는 재편의 단계를 거친다고 설정해 시대마다 다른 정치 문제와 인물 역할을 배치하는 서사적 역사 모형. 모든 실제 국가가 같은 경로를 따른다는 법칙은 아니다. 팽창기에 있는 신흥 제국, 과거의 흔적만 남은 제국, 쇠퇴 후 다시 일어서는 제국을 한 시간축에서 비교할 수 있다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"제국 체제","entry_url":"cards/MEJE-KW-000408/index.html"},{"id":"MEJE-KW-000409","row_version":2,"title":"정복을 목표로 하는 악역 제국","original":"The Empire","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01330","ML-T01333"],"summary":"광범위한 정복이나 지배권 확대를 목표로 삼아 주인공 세력과 맞서는 거대 국가형 적대자. 황제·군대·관료제·종속 지역을 통해 개인 악역보다 큰 위협으로 작동한다. 제국 체제라는 정치 구조가 언제나 악역인 것은 아니며, 이 카드는 작품 속 적대 역할에 한정한다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"제국 체제","entry_url":"cards/MEJE-KW-000409/index.html"},{"id":"MEJE-KW-000410","row_version":1,"title":"과거의 흔적만 남은 제국","original":"Vestigial Empire","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01330","ML-T01333"],"summary":"넓은 영토와 지배력을 잃었지만 옛 제국의 명칭·제도·도로·언어·의례가 남아 있는 국가 또는 지역. 남은 유산이 현재의 권력 관계와 기억을 둘러싼 갈등을 만든다. 쇠퇴 후 다시 일어서는 제국은 이 상태에서 의도적으로 세력을 되찾으려는 전개다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"제국 체제","entry_url":"cards/MEJE-KW-000410/index.html"},{"id":"MEJE-KW-000411","row_version":2,"title":"여성 전투 인물이 압도적인 세계","original":"World of Action Girls","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"주요 여성 인물 다수가 전투나 위험 대응에 능숙하고 남성 전투 인물은 상대적으로 드문 인물 분포 설정. 개별 인물의 성별이 능력을 결정한다는 뜻이 아니라, 작품이 어떤 사람들을 행동의 중심에 놓는지 보여 주는 구성이다. 인물 다수가 강자로 묘사되는 세계는 성별과 관계없이 거의 모두가 강자인 경우다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000411/index.html"},{"id":"MEJE-KW-000412","row_version":2,"title":"치안 조직 전반이 무너진 사회","original":"World of Bad Cops","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"경찰이나 치안 기관의 부패·무능·폭력이 일부 인물의 일탈을 넘어 조직 전체의 일상처럼 나타나는 사회 설정. 시민이 공적 보호를 기대하기 어려워지고 비공식 해결자나 자구책이 중요해진다. 한 명의 나쁜 경찰을 다루는 이야기와 조직 구조를 다루는 이 카드는 범위가 다르다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-000412/index.html"},{"id":"MEJE-KW-000413","row_version":2,"title":"인물 다수가 강자로 묘사되는 세계","original":"World of Badass","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"주요 인물뿐 아니라 평범해 보이는 주변 인물까지 각자의 방식으로 높은 생존력이나 전투 능력을 보이는 세계 설정. 강함이 예외적 재능이 아니라 이야기의 기본 기대치가 된다. 여성 전투 인물이 압도적인 세계는 그중 여성 전투 인물의 비중에 초점을 둔다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000413/index.html"},{"id":"MEJE-KW-000414","row_version":1,"title":"여성 인물의 체형이 일률적으로 풍만한 세계","original":"World of Buxom","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"여성 등장인물 대부분이 비슷하게 풍만한 체형으로 그려져 특정 외형이 작품의 기본값처럼 반복되는 시각 디자인 관습. 화풍·제작 방식·작가 취향이 원인일 수 있으며 인물의 성격이나 실제 사람의 몸을 평가하는 개념은 아니다. 남성 인물의 체형이 일률적으로 근육질인 세계와 비교할 수 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-000414/index.html"},{"id":"MEJE-KW-000415","row_version":1,"title":"규칙이 뒤섞이는 혼돈의 세계","original":"World of Chaos","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"공간·생물·사건의 결합이 수시로 달라져 인물이 안정된 자연 법칙이나 일상 경험을 믿기 어려운 세계. 예측보다 직관과 적응이 중요해지고 경이로움과 위험이 함께 나타난다. 평범한 일상에 기이함이 넘치는 세계는 낯선 것들이 자주 등장해도 일상의 겉모습은 유지되는 경우다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000415/index.html"},{"id":"MEJE-KW-000416","row_version":4,"title":"판단 착오가 집단적으로 반복되는 세계","original":"World of Dumbass","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"다수의 인물이 분명한 정보나 위험을 계속 놓쳐 소수의 관찰자와 대비되는 세계 설정. 반복되는 오해가 희극, 풍자 또는 권력 불균형을 만들 수 있다. 원인이 교육·선전·억압인지, 이야기의 편의를 위한 인물 배치인지에 따라 해석이 달라진다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000416/index.html"},{"id":"MEJE-KW-000417","row_version":1,"title":"동물이 인간의 사회 역할을 맡는 세계","original":"World of Funny Animals","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12","ML-T01108","ML-T01111"],"summary":"사람 대신 동물이 직업·가족·도시·제도를 이루며 사회 구성원으로 살아가는 세계. 동물의 생태가 이야기 규칙에 반영될 수도, 외형만 다르고 인간 사회와 비슷하게 작동할 수도 있다. 포유류 중심의 의인화 동물 세계는 등장 종의 범위를 좁힌 경우다.","accent":"#62816F","tab":"#778F70","facet":"존재·종족","bookmark":"의인화 동물","entry_url":"cards/MEJE-KW-000417/index.html"},{"id":"MEJE-KW-000418","row_version":3,"title":"일상까지 과장 연기하는 세계","original":"World of Ham","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"주요 인물 대부분이 평범한 대화와 행동까지 큰 몸짓·강한 발성·극적인 감정으로 표현하는 연출 관습. 일부 인물만 과장되는 것과 달리 작품 전체의 표현 수위가 높아진다. 실제 세계의 법칙보다 연기와 화면의 스타일을 가리킨다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-000418/index.html"},{"id":"MEJE-KW-000419","row_version":1,"title":"무례함이 일상화된 사회","original":"World of Jerkass","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"주요 인물과 주변 사회 모두에서 무시·모욕·이기적 행동이 흔하게 나타나 대인 신뢰가 낮은 작품 속 사회. 냉소적 코미디나 사회 풍자를 만들 수 있지만 모든 인물이 같은 이유로 행동하는 것은 아니다. 냉소적 대화가 기본인 세계는 말투의 우세에 초점을 둔다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-000419/index.html"},{"id":"MEJE-KW-000420","row_version":2,"title":"포유류 중심의 의인화 동물 세계","original":"World of Mammals","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12","ML-T01108","ML-T01111"],"summary":"여러 종류의 의인화 동물이 나오는 작품에서 지적 사회의 구성원이 거의 모두 육상 포유류로 그려지는 종 선택 관습. 조류·파충류·해양 생물 등이 드물거나 일반 동물로 남아 있을 수 있다. 동물이 인간의 사회 역할을 맡는 세계 중에서도 어떤 동물을 인물로 삼는지에 초점을 둔다.","accent":"#62816F","tab":"#778F70","facet":"존재·종족","bookmark":"의인화 동물","entry_url":"cards/MEJE-KW-000420/index.html"},{"id":"MEJE-KW-000421","row_version":2,"title":"가면을 늘 쓰는 사회","original":"World of Masks","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"가면 착용이 축제나 특수 임무를 넘어 평상시의 관습이나 의무가 된 사회 설정. 얼굴 공개 여부가 신분·소속·친밀감의 표시가 되고, 가면을 벗은 인물이 예외로 보일 수 있다. 개별 가면 쓴 인물보다 사회 전체의 규칙에 초점을 둔다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-000421/index.html"},{"id":"MEJE-KW-000422","row_version":1,"title":"남성 인물의 체형이 일률적으로 근육질인 세계","original":"World of Muscle Men","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"남성 등장인물 대부분이 비슷하게 큰 근육을 가진 모습으로 그려져 특정 외형이 작품의 기본값처럼 반복되는 시각 디자인 관습. 인물 간 외형 차이가 줄어들거나 장르의 과장된 힘 이미지를 드러낸다. 여성 인물의 체형이 일률적으로 풍만한 세계와 비교할 수 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-000422/index.html"},{"id":"MEJE-KW-000423","row_version":1,"title":"일상의 모든 것이 수수께끼인 세계","original":"World of Mysteries","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"평범한 사람·사물·표지까지 미해결 사연이나 숨은 관계를 지닌 것처럼 제시되는 세계. 하나의 사건을 푸는 추리보다 세계 전체의 정보가 계속 새 질문을 낳는 데 초점을 둔다. 규칙이 뒤섞이는 혼돈의 세계는 인과와 환경의 불안정성이 더 강하다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000423/index.html"},{"id":"MEJE-KW-000424","row_version":2,"title":"말장난으로 가득한 대화와 서술","original":"World of Pun","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01982","ML-T01990"],"summary":"한두 인물의 버릇을 넘어 대사·지명·표제·해설에 말장난이 끊임없이 등장하는 언어적 표현 관습. 어휘의 소리와 뜻이 이야기의 유머나 세계 분위기를 만든다. 개별 말장난보다 작품 전체의 사용 밀도에 초점을 둔다.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"말장난","entry_url":"cards/MEJE-KW-000424/index.html"},{"id":"MEJE-KW-000425","row_version":2,"title":"감정과 자아를 잃은 고요한 세계","original":"World of Silence","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"갈등을 없애려는 힘이나 통제 때문에 사람들의 감정·의지·개별성이 사라진 세계 상태. 소리가 없다는 뜻보다 삶의 반응이 멈춘 듯한 정적에 초점을 둔다. 평화의 외형과 인간다운 선택의 상실이 충돌하며, 원인이 무엇인지에 따라 구출·저항의 이야기가 달라진다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000425/index.html"},{"id":"MEJE-KW-000426","row_version":1,"title":"냉소적 대화가 기본인 세계","original":"World of Snark","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"대부분의 인물이 상황에 대한 불만과 비판을 짧고 재치 있는 빈정거림으로 주고받는 대화 관습. 친밀한 순간도 가능하지만 작품의 기본 말투는 냉소 쪽으로 기운다. 무례함이 일상화된 사회는 행동과 관계의 적대성이 더 강한 경우다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000426/index.html"},{"id":"MEJE-KW-000427","row_version":1,"title":"상징만으로 움직이는 서사 세계","original":"World of Symbolism","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21","ML-T01781","ML-T01783"],"summary":"사건의 물리적 인과보다 인물·사물·장면이 뜻하는 추상적 의미가 전개의 주된 연결 원리가 되는 표현 방식. 장면을 문자 그대로만 읽으면 설명이 부족해 보일 수 있으며, 해석 자체가 감상의 중심이 된다. 개별 상징주의적 표현을 사용하는 작품보다 상징의 지배 범위가 넓다.","accent":"#947C8F","tab":"#778F70","facet":"미학·스타일","bookmark":"상징주의적 표현","entry_url":"cards/MEJE-KW-000427/index.html"},{"id":"MEJE-KW-000428","row_version":2,"title":"비현실적인 머리색이 보편적인 세계","original":"World of Technicolor Hair","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"푸른색·초록색·보라색처럼 현실에서 드문 머리색이 여러 인물에게 자연스럽게 나타나고 주변도 특별하게 여기지 않는 시각 관습 또는 세계 설정. 타고난 특성인지 염색이 보편화된 사회인지 작품마다 다르다. 인물을 구별하는 디자인 효과와 세계 안의 설명을 구분한다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-000428/index.html"},{"id":"MEJE-KW-000429","row_version":1,"title":"평범한 일상에 기이함이 넘치는 세계","original":"World of Weirdness","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"겉으로는 익숙한 일상인데 초자연 현상·시간 여행·낯선 존재 같은 기이한 일이 곳곳에서 벌어지고 사람들이 이를 생활의 일부처럼 받아들이는 세계. 규칙이 뒤섞이는 혼돈의 세계는 환경 자체가 불안정한 경우이며, 이 카드는 일상의 틀과 비일상 요소가 공존하는 경우다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000429/index.html"},{"id":"MEJE-KW-000430","row_version":2,"title":"인간에게 편리한 행성이 흔한 우주","original":"All Planets Are Earth-Like","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313","ML-T01320"],"summary":"서로 다른 행성을 찾아가도 중력·대기·기온이 인간의 생활에 대체로 알맞아 별도의 생존 장비가 거의 필요 없는 우주 설정. 탐험과 만남을 쉽게 만들지만 행성마다 다른 환경 조건은 약해진다. 극도로 작은 거주 행성처럼 행성의 다른 특성을 과감히 축약하는 설정과 구별한다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"외계 행성","entry_url":"cards/MEJE-KW-000430/index.html"},{"id":"MEJE-KW-000431","row_version":1,"title":"극도로 작은 거주 행성","original":"Baby Planet","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313","ML-T01320"],"summary":"보통의 행성보다 훨씬 작으면서도 사람이 걷고 생활할 지표와 생태계를 갖춘 가상 천체. 실제 크기와 거주 가능 조건보다 장면의 친밀감이나 장난스러운 축척을 앞세운다. 인간에게 편리한 행성이 흔한 우주는 행성의 크기보다 환경의 편리함을 반복하는 경우다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"외계 행성","entry_url":"cards/MEJE-KW-000431/index.html"},{"id":"MEJE-KW-000432","row_version":1,"title":"행성 간 이동이 일상인 우주","original":"Casual Interplanetary Travel","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"같은 항성계의 다른 행성으로 가는 일이 길고 위험한 원정보다 통근·관광·상거래에 가까운 기술과 사회 기반을 갖춘 설정. 이동이 쉬워지면 행성 사이의 거리감보다 목적지의 생활과 관계가 앞에 나온다. 행성 여행 자체가 이야기인 전개는 이동 과정을 중심 사건으로 삼는다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000432/index.html"},{"id":"MEJE-KW-000433","row_version":2,"title":"행성 전체가 도시인 세계","original":"City Planet","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313","ML-T01320"],"summary":"행성 표면 대부분이 건물·교통망·기반 시설로 이어져 하나의 거대한 도시처럼 작동하는 세계. 식량과 자원 공급, 외부 행성과의 의존 관계가 설정의 핵심이 될 수 있다. 한 상품에 의존하는 행성 경제는 공간 전체의 도시화보다 산업의 단일화에 초점을 둔다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"외계 행성","entry_url":"cards/MEJE-KW-000433/index.html"},{"id":"MEJE-KW-000434","row_version":1,"title":"이동하기 편하도록 가까운 행성들","original":"Conveniently Close Planet","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313","ML-T01320"],"summary":"탐험·조우·구조가 자주 일어나도록 행성 사이의 거리와 항로상의 위치를 이야기 편의에 맞게 압축하는 공간 관습. 우주가 넓다는 감각보다 다음 목적지에 빨리 닿는 전개가 우선한다. 행성 간 이동이 일상인 우주는 거리뿐 아니라 이동 기술과 사회 인프라까지 쉬워진 경우다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"외계 행성","entry_url":"cards/MEJE-KW-000434/index.html"},{"id":"MEJE-KW-000435","row_version":2,"title":"행성 사이를 잇는 지상 관문","original":"Doorway Between Planets","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17","ML-T01508","ML-T01509"],"summary":"우주선을 타고 비행하지 않아도 한 행성의 지표에서 관문을 통과해 다른 행성의 지표로 바로 나가는 이동 방식. 관문이 많아지면 직장·거주지·시장 자체가 여러 행성에 걸쳐 형성될 수 있다. 행성 간 이동이 일상인 우주를 가능하게 하는 한 수단이며 순간이동의 장거리 응용이다.","accent":"#75799A","tab":"#8B739C","facet":"능력·기술·초자연","bookmark":"순간이동","entry_url":"cards/MEJE-KW-000435/index.html"},{"id":"MEJE-KW-000436","row_version":1,"title":"사망한 스타의 외계 이주설","original":"Elvis Has Left the Planet","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"유명인의 사망 소식을 실제 죽음이 아니라 외계 존재의 귀환이나 다른 행성으로의 출발로 뒤집는 대중문화 농담. 유명인 생존설에 우주적 설명을 붙인 변형이며, 실존 인물에 관한 사실 주장으로 쓰지 않는다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-000436/index.html"},{"id":"MEJE-KW-000437","row_version":3,"title":"문명 흔적만 남은 행성","original":"Ghost Planet","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313","ML-T01320"],"summary":"한때 도시와 사회가 존재했으나 지금은 주민이 거의 사라지고 건축물·기계·기록만 남은 외계 행성. 방문자는 폐허를 통해 사라진 문명의 규모와 몰락 원인을 추적한다. 과거의 흔적만 남은 제국은 정치 세력의 축소를, 이 카드는 행성 전체의 거주 공동체가 사라진 상태를 다룬다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"외계 행성","entry_url":"cards/MEJE-KW-000437/index.html"},{"id":"MEJE-KW-000438","row_version":1,"title":"우주에서 중요하지 않은 지구","original":"Insignificant Little Blue Planet","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"수많은 문명과 행성이 있는 세계에서 지구가 정치·경제·전략상 특별한 중심이 아닌 주변 지역으로 취급되는 관점. 인류가 스스로 기대한 중요성과 우주 사회의 무관심이 대비될 수 있다. 인간에게 편리한 행성이 흔한 우주처럼 지구와 비슷한 행성이 많은 설정과도 어울린다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000438/index.html"},{"id":"MEJE-KW-000439","row_version":2,"title":"행성 여행 자체가 이야기인 전개","original":"Interplanetary Voyage","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"다른 행성에 도착하는 결과만큼 출발 준비·항해·지연·선내 생활을 이야기의 중심에 놓는 우주여행 서사. 우주 공간을 건너는 시간이 인물 관계와 탐험의 경험을 만든다. 행성 간 이동이 일상인 우주는 이 과정을 대개 짧게 넘어간다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-000439/index.html"},{"id":"MEJE-KW-000440","row_version":2,"title":"금속이 부족한 행성","original":"Metal-Poor Planet","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313","ML-T01320"],"summary":"사회가 쉽게 채굴할 수 있는 금속 자원이 적어 건축·도구·기계·교역의 경로가 달라지는 행성 설정. 부족한 재료를 다른 자원이나 외부 수입으로 보완하는 방식이 세계의 기술과 정치에 영향을 준다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"외계 행성","entry_url":"cards/MEJE-KW-000440/index.html"},{"id":"MEJE-KW-000441","row_version":2,"title":"한 행성에 여러 문화가 공존함","original":"Multicultural Alien Planet","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"하나의 외계 행성 안에도 여러 언어·지역·정치체·생활 양식이 공존하도록 구성한 세계 설정. 종족이나 행성 하나를 한 성격으로 대표시키는 한 행성이 하나의 문화로 환원되기와 대비된다. 서로 다른 집단의 관계까지 설계할 때 행성의 내부가 입체적으로 보인다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-000441/index.html"},{"id":"MEJE-KW-000442","row_version":1,"title":"모성의 이름으로 불리는 외계 종족","original":"Named After Their Planet","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"외계 종족의 이름을 출신 행성 이름에서 만들어 그 행성의 모든 구성원을 한 집단처럼 부르는 명명 관습. 출신지와 생물학적 종, 정치적 소속이 서로 같은지에 따라 의미가 달라진다. 한 행성에 여러 문화가 공존함에서는 한 이름만으로 내부 집단을 설명하기 어려울 수 있다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000442/index.html"},{"id":"MEJE-KW-000443","row_version":1,"title":"한 상품에 의존하는 행성 경제","original":"One-Product Planet","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"한 행성이 특정 상품이나 서비스의 주요 공급지로 알려져 다른 행성과 그 분야를 중심으로 거래하는 경제 설정. 실제 내부 산업은 다양할 수도 있으므로 외부의 이미지와 생활 전체를 구분한다. 한 행성이 하나의 문화로 환원되기는 경제가 아닌 행성 문화의 단일화다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-000443/index.html"},{"id":"MEJE-KW-000444","row_version":1,"title":"살기 좋은 낙원 행성","original":"Paradise Planet","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313","ML-T01320"],"summary":"쾌적한 환경·아름다운 자연·안정된 일상으로 여러 세계의 방문객이 선망하는 행성. 실제 거주 조건과 외부에서 소비하는 낙원 이미지가 같을 수도 다를 수도 있다. 행성 전체가 도시인 세계와는 공간의 인상이 다르지만, 자연과 도시가 함께 존재하는 경우도 가능하다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"외계 행성","entry_url":"cards/MEJE-KW-000444/index.html"},{"id":"MEJE-KW-000445","row_version":1,"title":"행성 하나를 통째로 지배하는 인물","original":"Planet Baron","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"하나의 행성 전체에 대해 실질적인 통치권이나 소유권을 주장하는 인물형. 더 큰 은하 질서에서는 지역 통치자일 수 있지만 행성 내부 주민에게는 막강한 권력자다. 제국 체제처럼 여러 지역을 묶는 구조와 권력의 범위가 다르다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000445/index.html"},{"id":"MEJE-KW-000446","row_version":1,"title":"행성 파괴급 존재와 장치","original":"Planet Destroyer","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"행성의 환경과 지표를 되돌리기 어려울 만큼 파괴할 수 있는 존재·무기·현상. 능력의 규모를 단번에 보여 주어 여러 사회에 공통의 위협을 만든다. 행성을 먹는 존재는 파괴와 함께 행성의 물질이나 생명력을 섭취하는 하위 형태다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000446/index.html"},{"id":"MEJE-KW-000447","row_version":1,"title":"행성을 먹는 존재","original":"Planet Eater","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12","ML-T01148","ML-T01152"],"summary":"행성 자체나 그 생태계의 에너지를 먹이로 삼아 세계를 소진시키는 거대한 존재. 파괴가 단순한 공격이 아니라 생존·욕구·본성의 일부가 되면서 우주적 위협을 이룬다. 행성 파괴급 존재와 장치 중에서도 섭취가 핵심인 경우다.","accent":"#62816F","tab":"#A07A87","facet":"존재·종족","bookmark":"우주적 존재","entry_url":"cards/MEJE-KW-000447/index.html"},{"id":"MM-UNSET-000009","row_version":3,"title":"유명인 생존설","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"유명인 생존설은 사망했다고 알려진 유명인이 사실은 살아 있다는 주장을 가리킨다. 작품에 적용할 때는 인물의 생존을 둘러싼 추측이나 음모론이 핵심인지, 공식적으로 생존이 확인된 반전인지 구별한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MM-UNSET-000009/index.html"},{"id":"MM-UNSET-000010","row_version":3,"title":"한 행성이 하나의 문화로 환원되기","original":"Planet of Hats","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"행성이나 종족 구성원 대다수를 한 가지 직업·성격·관습으로 설명해 복잡한 사회를 빠르게 알아볼 수 있는 표지로 만드는 창작 관습. 기억하기 쉽지만 내부의 지역·세대·개인 차이를 가릴 수 있다. 한 행성에 여러 문화가 공존함은 같은 행성 안의 차이를 적극적으로 보여 준다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MM-UNSET-000010/index.html"},{"id":"MEJE-KW-000448","row_version":1,"title":"한 지역의 이름이 세계 전체의 이름이 되기","original":"Planet England","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"이야기가 처음 다룬 나라나 도시의 이름을 배경이 확장된 뒤에도 행성·세계 전체의 이름으로 사용하는 명명 관습. 익숙한 이름을 유지하는 대신 다른 지역이 중심 지역의 일부처럼 보일 수 있다. 한 행성에 여러 문화가 공존함을 드러내려면 지역과 세계의 이름을 구분할 필요가 생긴다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000448/index.html"},{"id":"MEJE-KW-000449","row_version":2,"title":"지옥을 돌파 가능한 게임 스테이지로 만들기","original":"Planet Heck","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"원래 탈출하기 어렵거나 최후의 장소처럼 보이는 지옥을 플레이어가 진입해 적을 쓰러뜨리고 나올 수 있는 게임 구역으로 구성하는 관습. 분위기와 적의 종류보다 공략 가능한 목표·경로·보상의 설계가 앞선다. 사후세계의 구조가 세계 안의 질서를 다룬다면 이 카드는 게임의 진행 구조를 다룬다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-000449/index.html"},{"id":"MEJE-KW-000450","row_version":1,"title":"행성 자원을 약탈하며 옮겨 다니는 세력","original":"Planet Looters","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"한 행성의 자원이나 생태계를 강제로 빼앗고 다음 행성으로 이동하는 외계 집단의 활동 방식. 필요한 자원이 무엇인지와 이미 사는 주민을 어떻게 대하는지가 갈등의 핵심이 된다. 행성을 먹는 존재는 섭취 자체가 생존 방식이며, 이 카드는 조직적인 채취와 약탈을 다룬다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-000450/index.html"},{"id":"MEJE-KW-000451","row_version":2,"title":"한 인물의 버릇이 종족 문화가 되기","original":"Planet of Copyhats","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"처음 등장한 외계 인물의 독특한 말투나 행동을 나중에 나온 동족 모두의 공통 문화로 확장하는 창작 방식. 한 인물의 개성이 사회 전체의 규칙이 되면서 초기 캐릭터가 오히려 평범한 구성원처럼 보일 수 있다. 한 행성이 하나의 문화로 환원되기의 문화가 등장 순서에 따라 뒤늦게 정해진 경우다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-000451/index.html"},{"id":"MEJE-KW-000453","row_version":1,"title":"모두가 같은 이름을 쓰는 사회","original":"Planet of Steves","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"한 사회의 구성원 다수가 같은 개인 이름을 써서 외부인이 사람을 구별하기 어려워지는 명명 설정. 같은 이름이 그 사회 안에서는 다른 단서와 결합해 충분할 수도 있으며, 혼란 자체가 희극이 될 수도 있다. 한 행성이 하나의 문화로 환원되기의 명명 관습으로 나타날 수 있다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000453/index.html"},{"id":"MEJE-KW-000454","row_version":1,"title":"행성 크기의 우주선","original":"Planet Spaceship","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16","ML-T01454","ML-T01461"],"summary":"행성에 맞먹는 규모의 이동식 우주선이나 추진 장치를 갖춘 천체. 대규모 주민을 싣거나 한 문명의 생산력을 보여 주며, 이동하는 도시와 세계의 경계를 흐린다. 행성을 궤도 밖으로 옮기기는 기존 행성의 위치를 바꾸는 사건이고 이 카드는 이동 가능한 구조물 자체다.","accent":"#8E8263","tab":"#7D8FA3","facet":"사물·도구·자원","bookmark":"우주선 기체","entry_url":"cards/MEJE-KW-000454/index.html"},{"id":"MEJE-KW-000455","row_version":2,"title":"지구를 테라라고 부르기","original":"Planet Terra","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"미래·대체역사·우주 배경에서 지구를 라틴어 계열 이름인 '테라'로 부르는 명명 관습. 지구를 다른 행성과 나란히 놓거나 국제적인 공통 이름을 쓰는 분위기를 만든다. 모성의 이름으로 불리는 외계 종족과 결합하면 지구인을 테라인으로 부를 수도 있다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000455/index.html"},{"id":"MEJE-KW-000456","row_version":2,"title":"태양계의 미지의 추가 행성","original":"Planet X","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"알려진 태양계 지도 밖에 아직 발견되지 않은 행성이 존재한다고 가정해 탐사·고대 문명·낯선 생명체의 무대로 쓰는 설정. 그 행성의 실제 존재 여부보다 가까운 우주에도 빈 공간이 남아 있다는 서사적 가능성에 초점을 둔다. 행성 여행 자체가 이야기인 전개의 목적지가 될 수 있다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-000456/index.html"},{"id":"MEJE-KW-000457","row_version":1,"title":"행성 핵을 조작하기","original":"Planetary Core Manipulation","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"행성 내부의 핵에 직접 손을 대어 에너지를 얻거나 자기장·지각·궤도에 영향을 주려는 능력 또는 기술. 회복을 위한 개입과 파괴를 위한 개입을 구분할 수 있다. 실패하거나 공격으로 쓰이면 행성 파괴급 존재와 장치의 위협으로 이어질 수 있다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000457/index.html"},{"id":"MEJE-KW-000458","row_version":2,"title":"행성 전체가 하나의 국가","original":"Planetary Nation","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"거주 행성의 여러 지역이 하나의 정부나 정치 공동체 아래 묶여 있는 세계 설정. 작은 초기 식민지일 수도 오랜 통합의 결과일 수도 있다. 한 행성에 여러 문화가 공존함과 양립할 수 있으며 정치적 통일이 곧 문화적 단일성을 뜻하지 않는다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-000458/index.html"},{"id":"MEJE-KW-000459","row_version":1,"title":"행성에 기생하는 존재","original":"Planetary Parasite","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12","ML-T01148","ML-T01152"],"summary":"행성을 숙주 삼아 자원이나 생명력을 소모하며 성장하고, 다음 행성으로 퍼질 새 개체를 만드는 존재. 행성을 먹는 존재는 섭취가 목적이고, 이 카드는 행성 안에서 번식 주기가 진행된다는 점이 핵심이다. 행성 자원을 약탈하며 옮겨 다니는 세력은 조직적 채취 행위에 가깝다.","accent":"#62816F","tab":"#A07A87","facet":"존재·종족","bookmark":"우주적 존재","entry_url":"cards/MEJE-KW-000459/index.html"},{"id":"MEJE-KW-000460","row_version":1,"title":"행성을 궤도 밖으로 옮기기","original":"Planetary Relocation","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"행성이나 큰 위성을 원래 궤도에서 떼어 다른 위치로 이동시키는 거대 기술 또는 사건. 피난·개조·공격처럼 목적이 달라지며 이동 후의 하늘과 환경도 새롭게 설정해야 한다. 행성 크기의 우주선은 스스로 이동하도록 설계된 구조물에 가깝다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000460/index.html"},{"id":"MEJE-KW-000461","row_version":2,"title":"낯선 행성에서 펼치는 모험 로망스","original":"Planetary Romance","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"우주 이동을 계기로 낯선 행성에 도착한 뒤 그곳의 지리·사회·위험을 탐험하는 모험 서사 유형. 과학소설의 입구를 지나 판타지 모험에 가까운 현지 경험을 길게 다룬다. 여기서 로망스는 연애 필수를 뜻하지 않으며, 행성 여행 자체가 이야기인 전개보다 목적지의 모험에 무게를 둔다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-000461/index.html"},{"id":"MEJE-KW-000462","row_version":2,"title":"행성을 마을처럼 다루는 우주","original":"Planetville","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"우주여행 이야기에서 행성 하나를 지상의 마을이나 나라 하나처럼 단순한 사회 단위로 취급하는 세계 설계 관습. 이동과 정치 관계를 쉽게 그릴 수 있지만 행성 내부의 크기와 다양성은 줄어든다. 행성 전체가 하나의 국가는 정치 구조를, 이 카드는 서사에서 행성을 쓰는 축척을 다룬다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000462/index.html"},{"id":"MEJE-KW-000463","row_version":2,"title":"휴양과 향락에 특화된 행성","original":"Pleasure Planet","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"관광·공연·놀이·사교 등 방문객의 즐거움을 주요 산업과 이미지로 삼는 행성 사회. 가족 휴양지부터 성인 향락지까지 모습이 다르며 실제 주민의 일상은 관광 이미지 밖에 남을 수 있다. 살기 좋은 낙원 행성은 자연과 거주 여건의 이상에, 이 카드는 방문객을 위한 서비스에 초점을 둔다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-000463/index.html"},{"id":"MEJE-KW-000464","row_version":1,"title":"고리 형태의 거주 세계","original":"Ring World Planet","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"거주 가능한 면을 고리 안쪽에 두어 지평선이 위로 휘어 보이는 인공 세계 형태. 회전·채광·이동 경로가 일반 행성과 다른 생활 조건을 만든다. 행성 크기의 우주선처럼 거대한 인공 구조물이지만, 이 카드는 추진 장치보다 거주 지형의 형태에 초점을 둔다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-000464/index.html"},{"id":"MEJE-KW-000465","row_version":1,"title":"별 없이 떠도는 행성","original":"Rogue Planet","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313","ML-T01320"],"summary":"항성의 안정된 궤도에 매이지 않고 우주를 떠도는 행성. 외부 빛이 적은 환경과 잃어버린 고향의 흔적이 탐험의 동기가 될 수 있다. 행성을 궤도 밖으로 옮기기는 누군가 위치를 바꾸는 사건이고, 이 카드는 그 결과나 자연적인 떠돌이 상태다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"외계 행성","entry_url":"cards/MEJE-KW-000465/index.html"},{"id":"MEJE-KW-000466","row_version":2,"title":"위협을 증명하려 먼저 희생되는 행성","original":"Sacrificial Planet","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"주인공의 세계에 닥칠 위험을 관객이 미리 이해하도록 다른 행성이 먼저 파괴되거나 황폐해지는 서사 장치. 멸망한 장소는 위협의 규모를 보여 주고 다음 목표를 막아야 할 이유를 만든다. 행성 파괴급 존재와 장치나 행성을 먹는 존재가 원인이 될 수 있다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-000466/index.html"},{"id":"MEJE-KW-000467","row_version":1,"title":"한 행성에 언어가 하나뿐인 세계","original":"Single Language Planet","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"행성의 여러 지역과 사회가 사실상 하나의 언어만 사용하도록 설정된 세계. 모두가 통하는 공용어가 있으면서 다른 지역 언어도 존재하는 경우와 구별한다. 한 행성에 여러 문화가 공존함과 반드시 모순되지는 않지만 언어 차이의 표현은 줄어든다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000467/index.html"},{"id":"MEJE-KW-000468","row_version":2,"title":"한 가지 환경으로 채운 행성","original":"Single-Biome Planet","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313","ML-T01320"],"summary":"행성 전체가 사막·숲·바다 같은 하나의 대표 환경으로 그려져 지역마다 다른 기후와 생태가 잘 드러나지 않는 세계 설정. 행성의 인상을 빠르게 전달하지만 내부 탐험의 차이는 줄일 수 있다. 극도로 작은 거주 행성은 천체 크기를 줄이는 설정이고, 이 카드는 환경의 종류를 줄인다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"외계 행성","entry_url":"cards/MEJE-KW-000468/index.html"},{"id":"MEJE-KW-000469","row_version":1,"title":"항성에 같은 면을 보이는 행성","original":"Tidally Locked Planet","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313","ML-T01320"],"summary":"공전과 자전이 맞물려 늘 같은 면이 항성을 향하는 행성. 밝은 쪽과 어두운 쪽, 그 사이 경계 지역의 생활과 이동을 다르게 설계할 수 있다. 한 가지 환경으로 채운 행성처럼 표면 전체가 같은 조건이라는 뜻은 아니다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"외계 행성","entry_url":"cards/MEJE-KW-000469/index.html"}]}.cards;